mapper.sql:
WHERE purchase_orders.status >= 0

    AND (
    purchase_orders.po_code LIKE CONCAT("%", #{filter.searchText}, "%")
    OR purchase_requests.pr_code LIKE CONCAT("%", #{filter.searchText}, "%")
    OR pv_requests.code LIKE CONCAT("%", #{filter.searchText}, "%")
    OR payment_terms.name LIKE CONCAT("%", #{filter.searchText}, "%")
    OR vendors.name LIKE CONCAT("%", #{filter.searchText}, "%")
    )


    AND purchase_orders.order_date >= #{filter.dateFrom}


    AND purchase_orders.order_date <= #{filter.dateTo}


    AND purchase_orders.status = #{filter.status}


    AND purchase_orders.vendor_id = #{filter.vendorId}


    AND purchase_orders.po_type = #{filter.poType}


    AND purchase_orders.location_group_id = #{filter.warehouseId}


    AND purchase_orders.location_id = #{filter.locationId}


    AND purchase_orders.created_by = #{userId}




            AND purchase_orders.balance > 0


            AND purchase_orders.balance = 0

mapper.select:
SELECT



ORDER BY


        ${filter.orderBy}


        purchase_orders.id DESC


LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT COUNT(id)
FROM purchase_requests
WHERE is_active = 1 AND name = #{name}
 AND id != #{id}

