mapper.update:
UPDATE purchase_orders SET
  status = 0,
  modified = NOW(),
  modified_by = #{userId}
WHERE id = #{id};

mapper.select:
SELECT po_code
FROM purchase_orders
WHERE id = #{id}

mapper.update:
UPDATE inventory_valuations
SET purchase_order_id = #{purchaseBillId}
WHERE purchase_order_id = #{purchaseOrderId}
  AND is_active = 1
  AND type = 'Bill'

mapper.select:
SELECT SUM(qty) FROM
    (

        SELECT SUM(qty * conversion) AS qty
        FROM purchase_request_details
        WHERE purchase_request_id = #{purchaseOrderId}

        UNION

        SELECT IFNULL(SUM(qty),0) AS qty
        FROM purchase_request_services
        WHERE purchase_request_id = #{purchaseOrderId}

    ) AS combined

choose.when:
